let P=REPORT.runs[0]?.payload||{};
function _typedFromB64(text,dtype){const bin=atob(text||''),bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);const buf=bytes.buffer;return dtype==='uint8'?new Uint8Array(buf):dtype==='uint32'?new Uint32Array(buf):new Uint16Array(buf)}
function _decodeCategory(enc){if(enc&&!enc.codes&&enc.codes_b64)enc.codes=_typedFromB64(enc.codes_b64,enc.dtype||'uint16');return enc}
function _decodeCoordinate(enc){if(!enc)return [];const q=_typedFromB64(enc.data_b64,'uint16'),lo=Number(enc.minimum)||0,hi=Number(enc.maximum)||lo;if(hi<=lo)return Array.from({length:q.length},()=>lo);const scale=(hi-lo)/65535;return Array.from(q,v=>lo+v*scale)}
function _decodeRunPayload(payload){if(payload?.points){Object.values(payload.points.fields||{}).forEach(_decodeCategory);Object.values(payload.points.resolution_clusters||{}).forEach(_decodeCategory);if(payload.points.coords_q16&&!payload.points._decoded){payload.points.x=_decodeCoordinate(payload.points.coords_q16.x);payload.points.y=_decodeCoordinate(payload.points.coords_q16.y);payload.points._decoded=true}}}
REPORT.runs.forEach(r=>_decodeRunPayload(r.payload));
function isMultiSeed(){return REPORT.runs.length>1}
