function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fmt(v){if(v===null||v===undefined||Number.isNaN(v))return '—';if(typeof v==='number'){if(!Number.isFinite(v))return '—';const a=Math.abs(v);if(a!==0&&a<1e-4)return v.toExponential(3);if(a>=1000)return v.toLocaleString(undefined,{maximumFractionDigits:2});return v.toLocaleString(undefined,{maximumFractionDigits:4});}return String(v)}
function fmtScore(v){if(typeof v!=='number'||!Number.isFinite(v))return '—';const a=Math.abs(v);if(a!==0&&a<1e-4)return v.toExponential(3);return v.toLocaleString(undefined,{minimumFractionDigits:4,maximumFractionDigits:4})}
function fmtCount(v){return typeof v==='number'&&Number.isFinite(v)?Math.round(v).toLocaleString():'—'}
function pct(v){return typeof v==='number'&&Number.isFinite(v)?(100*v).toLocaleString(undefined,{maximumFractionDigits:1})+'%':'—'}
function card(k,v,s=''){return `<div class="metric-card"><div class="k">${esc(k)}</div><div class="v">${esc(fmt(v))}</div>${s?`<div class="s">${esc(s)}</div>`:''}</div>`}
function scoreCard(k,v,s=''){return `<div class="metric-card"><div class="k">${esc(k)}</div><div class="v">${esc(fmtScore(v))}</div>${s?`<div class="s">${esc(s)}</div>`:''}</div>`}
function toast(message,type='info'){const el=document.getElementById('toast');if(!el)return;el.textContent=message;el.className='toast show'+(type==='error'?' error':'');clearTimeout(toast._timer);toast._timer=setTimeout(()=>el.className='toast',2200)}
function debounce(fn,delay=160){let t;return(...args)=>{clearTimeout(t);t=setTimeout(()=>fn(...args),delay)}}

const COLUMN_LABELS={ASW_true_on_latent:'Historical within-subset ASW',ASW_selected_cells_in_full_latent:'Selected-cell ASW in full latent',knn_local_recovery_adjusted:'kNN local recovery (support-adjusted)',knn_local_recovery:'kNN local recovery (raw, support-limited)',knn_same_label_fraction:'kNN same-label fraction',knn_expected_fraction:'Abundance-null neighbor fraction',knn_max_achievable_fraction:'kNN achievable ceiling',knn_mean_neighbors:'Mean realized kNN degree',knn_valid_cells:'Cells with kNN neighbors',failure_match_count:'Matched failure rules',failure_match_count_v2:'Matched failure rules (v2)',preserved_fraction:'Legacy preserved fraction',resolution_limited_fraction:'Resolution-limited fraction (v2)',best_cluster_precision:'Best-cluster precision',best_cluster_recall:'Best-cluster recall',best_cluster_f1:'Best-cluster F1',ARI_true_vs_cluster:'ARI: labels vs clusters',AMI_true_vs_cluster:'AMI: labels vs clusters',Accuracy:'Majority-vote accuracy',F1_macro:'Macro F1',F1_weighted:'Weighted F1',G_Mean:'G-Mean',cell_type:'Cell type',predicted_count:'Predicted count',true_positive:'True positive',false_positive:'False positive',false_negative:'False negative',inverse_purity:'Dominant-cluster capture',within_type_batch_nmi:'Within-type batch NMI',n_clusters_found_in:'Clusters containing target',n_clusters_assigned_to:'Clusters assigned to target',dominant_wrong_label:'Dominant wrong label',dominant_wrong_fraction:'Dominant wrong fraction',failure_archetype:'Legacy failure archetype',failure_rationale:'Legacy failure rationale',failure_archetype_v2:'Resolution-aware failure archetype',failure_rationale_v2:'Resolution-aware failure rationale',failure_matched_archetypes_v2:'Matched failure rules (v2)',curation_source:'Curation source',parent_type:'Parent type',metric_type:'Metric group',n_valid:'Valid populations',support:'Support',precision:'Precision',recall:'Recall',f1:'F1',scenario:'Scenario',distribution:'Distribution',topology:'Topology'};
const COLUMN_HELP={ASW_true_on_latent:'Historical silhouette computed within the currently evaluated subset. For the rare subset it does not include abundant populations as competitors; use Selected-cell ASW in full latent for rare-preservation interpretation.',ASW_selected_cells_in_full_latent:'Silhouette is computed with all cells present, then averaged only over the selected subset. This is the preferred ASW when asking whether rare cells remain separated from abundant populations.',knn_local_recovery_adjusted:'Primary local-recovery metric. It normalizes observed same-label neighborhoods against both the abundance null and the maximum achievable fraction given population support and realized graph degree. 0 is abundance-null, 1 is the support-aware achievable maximum, and negative values indicate below-null neighborhoods.',knn_local_recovery:'Historical/raw local-recovery score normalized only against abundance. It is retained for backward comparison but has a support-dependent ceiling for populations smaller than the realized graph degree.',knn_max_achievable_fraction:'Maximum same-label neighbor fraction achievable for this population given its support and realized graph degree. Context only, not a performance score.',knn_same_label_fraction:'Observed fraction of graph neighbors sharing the true cell-type label.',knn_expected_fraction:'Expected same-label neighbor fraction from global abundance. Context-only; this is not a performance score.',best_cluster_f1:'Best F1 obtained by matching this true population to any single discovered cluster. It avoids majority-label ownership competition but remains clustering-resolution dependent.',best_cluster_precision:'Precision of the single cluster that maximizes F1 for this true population.',best_cluster_recall:'Recall of the single cluster that maximizes F1 for this true population.',inverse_purity:'Fraction of this true cell type contained in its dominant cluster. Higher is better. Internal column name: inverse_purity.',within_type_batch_nmi:'NMI between batch labels and clusters within the target cell type. Lower values indicate less batch-associated cluster structure; interpret separately from recovery metrics.',ARI_true_vs_cluster:'Adjusted Rand Index between reference cell-type labels and Leiden clusters.',AMI_true_vs_cluster:'Adjusted Mutual Information between reference cell-type labels and Leiden clusters.',F1_macro:'Unweighted mean F1 across cell types.',F1_weighted:'F1 averaged with cell-type support as weights.',G_Mean:'Geometric mean of per-class recall.',precision:'For a target cell type, the fraction of predicted target cells that are true positives.',recall:'For a target cell type, the fraction of true target cells recovered by the majority-vote prediction.',f1:'Harmonic mean of precision and recall.',support:'Number of true cells in the target population.'};
Object.entries(P.metric_registry||{}).forEach(([key,info])=>{if(info?.label)COLUMN_LABELS[key]=info.label;if(info?.description)COLUMN_HELP[key]=info.description+(info.direction&&info.direction!=='context'?` Direction: ${info.direction}.`:'')});
function colLabel(c){return COLUMN_LABELS[c]||String(c).replaceAll('_',' ')}
function failureLabel(x){return ({preserved:'Preserved',resolution_limited:'Resolution limited',lineage_assimilation:'Lineage assimilation',lineage_leakage:'Lineage leakage',batch_driven_fragmentation:'Batch-driven fragmentation',mixed_or_uncertain:'Mixed / uncertain'})[x]||String(x||'Unknown')}
function failurePill(x,count=''){return `<span class="pill failure-${esc(x)}">${esc(failureLabel(x))}${count!==''?' · '+esc(count):''}</span>`}
function primaryFailure(row){return String(row?.failure_archetype_v2||row?.failure_archetype||'')}
function legacyFailure(row){return String(row?.failure_archetype||'')}
function rareOutcome(row){return primaryFailure(row)==='preserved'?'preserved':'not_preserved'}
function adjustedRecoveryDisplay(row){if(Number(row?.support)===1&&(row?.knn_local_recovery_adjusted===null||row?.knn_local_recovery_adjusted===undefined||!Number.isFinite(Number(row?.knn_local_recovery_adjusted))))return 'Not assessable — singleton';return fmt(row?.knn_local_recovery_adjusted)}
function outcomeLabel(x){return x==='preserved'?'Preserved':x==='not_preserved'?'Not preserved':'All outcomes'}
function outcomePill(x,count=''){const cls=x==='preserved'?'failure-preserved':'failure-mixed_or_uncertain';return `<span class="pill ${cls}">${esc(outcomeLabel(x))}${count!==''?' · '+esc(count):''}</span>`}
function cellHTML(col,value){if((col==='failure_archetype'||col==='failure_archetype_v2')&&value)return failurePill(value);if(col==='status'&&value)return `<span class="status">${esc(String(value).replaceAll('_',' '))}</span>`;if(col==='within_type_batch_nmi'&&(value===null||value===undefined||Number.isNaN(value)))return '<span title="Not assessable unless the target population spans at least two batches and at least two discovered clusters.">—</span>';const scoreCols=new Set(['ASW_true_on_latent','ASW_selected_cells_in_full_latent','knn_local_recovery_adjusted','knn_local_recovery','knn_same_label_fraction','knn_expected_fraction','knn_max_achievable_fraction','best_cluster_precision','best_cluster_recall','best_cluster_f1','inverse_purity','within_type_batch_nmi','ARI_true_vs_cluster','AMI_true_vs_cluster','Accuracy','F1_macro','F1_weighted','G_Mean','precision','recall','f1','dominant_wrong_fraction']);if(scoreCols.has(String(col))&&typeof value==='number'&&Number.isFinite(value))return esc(fmtScore(value));return esc(fmt(value))}
function csvCell(v){const s=String(v??'');return /[",\n]/.test(s)?'"'+s.replaceAll('"','""')+'"':s}
function downloadText(name,text,type='text/plain'){try{const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200);toast(`Saved ${name}`)}catch(err){console.error(err);toast('Export failed in this browser.','error')}}
function downloadPlot(id,name){const el=document.getElementById(id);if(!el||!el.data||!el.data.length){toast('No rendered plot is available to export.','error');return Promise.resolve(false)}return Plotly.downloadImage(el,{format:'png',filename:name,width:1700,height:1100,scale:2}).then(()=>{toast(`Exported ${name}.png`);return true}).catch(err=>{console.error(err);toast('Plot export failed in this browser.','error');return false})}
function field(name,i){const f=P.points?.fields?.[name];return f?f.categories[f.codes[i]]:'unknown'}
function encodedField(enc,i){return enc?enc.categories[enc.codes[i]]:'unknown'}
function numericField(name,i){const a=P.points?.numeric_fields?.[name];return a&&i<a.length?a[i]:null}
function decodeMarkerGene(gene){if(markerCache[gene])return markerCache[gene];const row=P.points?.marker_genes?.rows?.[gene];if(!row)return null;const bin=atob(row.data_b64),arr=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)arr[i]=bin.charCodeAt(i);markerCache[gene]=arr;return arr}
function markerApproxValue(gene,q){const row=P.points?.marker_genes?.rows?.[gene];return row?row.q01+(Number(q)/255)*(row.q99-row.q01):null}
function palette(n){const b=['#3157d5','#e04d4d','#0b9b72','#df941d','#714bd3','#d94c9b','#13a2ae','#e66c28','#4788e8','#78a827','#1598d4','#9b55d7','#34a853','#d83c64','#69778e'];return Array.from({length:n},(_,i)=>b[i%b.length])}
function hover(indices){return indices.map(i=>{const id=P.points?.cell_id&&P.points.cell_id.length?`Cell: ${P.points.cell_id[i]}<br>`:'';const adj=numericField('knn_local_recovery_adjusted_cell',i),raw=numericField('knn_local_recovery_cell',i);return id+`True type: ${field('celltype',i)}<br>Batch: ${field('batch',i)}<br>Scenario: ${field('scenario',i)}<br>Cluster: ${field('cluster',i)}<br>Prediction: ${field('prediction',i)}<br>Failure: ${field('failure_archetype',i)}${typeof adj==='number'?`<br>Adjusted kNN recovery: ${fmt(adj)}`:''}${typeof raw==='number'?`<br>Raw kNN recovery: ${fmt(raw)}`:''}`})}
function emptyHTML(title,text=''){return `<div class="empty-state"><b>${esc(title)}</b>${text?esc(text):''}</div>`}

function tableHTML(data,id,options={}){if(!data||!data.columns||!data.columns.length)return emptyHTML('No table data','No rows were produced for this section.');const showSearch=options.showSearch!==false,clickable=!!options.clickable;return `<div class="table-tools">${showSearch?`<input id="${id}-search" type="search" aria-label="Filter ${esc(id)} rows" placeholder="Filter rows…">`:''}<div class="export-group"><button class="btn ghost compact" data-export-current="${id}" title="Export the currently visible rows as CSV">Export view</button><button class="btn ghost compact" data-export-full="${id}" title="Export the complete source table as CSV">Export all</button></div></div><div class="table-scroll-shell"><div class="table-wrap"><table id="${id}"><thead><tr>${data.columns.map(c=>`<th data-col="${esc(c)}" title="${esc(COLUMN_HELP[c]||String(c))}" aria-sort="none">${esc(colLabel(c))}</th>`).join('')}</tr></thead><tbody>${data.rows.map((r,i)=>`<tr data-i="${i}" class="${clickable?'clickrow':''}">${data.columns.map(c=>`<td>${cellHTML(c,r[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="table-scroll-cue" aria-hidden="true">Scroll horizontally →</div></div>`}
function exportTable(viewData,fullData,id,current){const table=document.getElementById(id);if(!table)return;const cols=viewData.columns||[];let rows,headers;if(current){headers=cols.map(colLabel);rows=[...table.tBodies[0].rows].filter(r=>r.style.display!=='none').map(r=>[...r.cells].map(c=>c.textContent.trim()))}else{const src=fullData||viewData;headers=cols;rows=(src.rows||[]).map(r=>cols.map(c=>r[c]))}const lines=[headers,...rows].map(r=>r.map(csvCell).join(','));downloadText(id+(current?'_view':'_all_raw')+'.csv',lines.join('\n'),'text/csv;charset=utf-8')}
function wireTable(data,id,onRow=null,fullData=null){const t=document.getElementById(id),q=document.getElementById(id+'-search');if(!t)return;const sort={idx:-1,dir:1};t.querySelectorAll('th').forEach((th,idx)=>th.addEventListener('click',()=>{if(sort.idx===idx)sort.dir*=-1;else{sort.idx=idx;sort.dir=1}t.querySelectorAll('th').forEach(h=>{h.dataset.sort='';h.setAttribute('aria-sort','none')});th.dataset.sort=sort.dir===1?'asc':'desc';th.setAttribute('aria-sort',sort.dir===1?'ascending':'descending');const rows=[...t.tBodies[0].rows];rows.sort((a,b)=>{const av=a.cells[idx].textContent.trim(),bv=b.cells[idx].textContent.trim(),an=Number(av.replace(/,/g,'')),bn=Number(bv.replace(/,/g,''));const cmp=Number.isFinite(an)&&Number.isFinite(bn)?an-bn:av.localeCompare(bv,undefined,{numeric:true,sensitivity:'base'});return sort.dir*cmp});rows.forEach(r=>t.tBodies[0].appendChild(r))}));if(q)q.addEventListener('input',()=>{const z=q.value.trim().toLowerCase();[...t.tBodies[0].rows].forEach(r=>r.style.display=!z||r.textContent.toLowerCase().includes(z)?'':'none')});if(onRow)[...t.tBodies[0].rows].forEach(r=>r.addEventListener('click',()=>onRow(data.rows[Number(r.dataset.i)])));document.querySelector(`[data-export-current="${id}"]`)?.addEventListener('click',()=>exportTable(data,fullData||data,id,true));document.querySelector(`[data-export-full="${id}"]`)?.addEventListener('click',()=>exportTable(data,fullData||data,id,false));const wrap=t.closest('.table-wrap'),shell=t.closest('.table-scroll-shell');if(wrap&&shell){const updateCue=()=>{const scrollable=wrap.scrollWidth>wrap.clientWidth+2,atEnd=wrap.scrollLeft+wrap.clientWidth>=wrap.scrollWidth-3;shell.classList.toggle('is-scrollable',scrollable);shell.classList.toggle('at-end',!scrollable||atEnd)};wrap.addEventListener('scroll',updateCue,{passive:true});window.addEventListener('resize',debounce(updateCue,120));requestAnimationFrame(updateCue)}}
function findMetric(table,name){if(!table||!table.rows)return null;const r=table.rows.find(x=>String(x.metric||'').toLowerCase()===name.toLowerCase());return r?r.value??r.mean:null}


function failureMatches(row,rules){const out=[];const p=Number(row.precision),r=Number(row.recall),ip=Number(row.inverse_purity),nmi=Number(row.within_type_batch_nmi),nc=Number(row.n_clusters_found_in),dw=Number(row.dominant_wrong_fraction),adj=Number(row.knn_local_recovery_adjusted);const pr=rules.preserved||{};if(p>=pr.min_precision&&r>=pr.min_recall&&ip>=pr.min_inverse_purity)out.push('preserved');const as=rules.lineage_assimilation||{},assimilationCandidate=r<=as.max_recall&&dw>=as.min_dominant_wrong_fraction;const rl=rules.resolution_limited||{};if(assimilationCandidate&&Number.isFinite(adj)&&adj>=Number(rl.min_knn_local_recovery_adjusted)&&ip>=Number(rl.min_inverse_purity))out.push('resolution_limited');const fr=rules.batch_fragmentation||{};if(ip<=fr.max_inverse_purity&&nc>=fr.min_clusters&&Number.isFinite(nmi)&&nmi>=fr.min_within_type_batch_nmi)out.push('batch_driven_fragmentation');const le=rules.lineage_leakage||{};if(r>=le.min_recall&&p<=le.max_precision)out.push('lineage_leakage');if(assimilationCandidate)out.push('lineage_assimilation');const order=['preserved','resolution_limited','batch_driven_fragmentation','lineage_leakage','lineage_assimilation'];out.sort((a,b)=>order.indexOf(a)-order.indexOf(b));return out}
function classifyWithRules(row,rules){const m=failureMatches(row,rules);return {primary:m[0]||'mixed_or_uncertain',matches:m}}
function cloneJSON(x){return JSON.parse(JSON.stringify(x||{}))}
let sensitivityRules=cloneJSON(P.failure_rules||{});
const RULE_LABELS={min_precision:'Min precision',min_recall:'Min recall',min_inverse_purity:'Min inverse purity',max_inverse_purity:'Max inverse purity',min_clusters:'Min clusters',min_within_type_batch_nmi:'Min within-type batch NMI',max_precision:'Max precision',max_recall:'Max recall',min_dominant_wrong_fraction:'Min dominant wrong fraction',min_knn_local_recovery_adjusted:'Min adjusted kNN recovery'};
function thresholdControl(group,key,value){const integer=key==='min_clusters',min=integer?1:0,max=integer?12:1,step=integer?1:0.01;return `<div class="threshold-row"><label>${esc(RULE_LABELS[key]||key)} <b id="ruleval-${group}-${key}">${esc(fmt(value))}</b></label><input class="rule-slider" data-group="${esc(group)}" data-key="${esc(key)}" type="range" min="${min}" max="${max}" step="${step}" value="${esc(value)}"></div>`}
function renderFailureSensitivity(){const host=document.getElementById('failureSensitivityHost');if(!host)return;const rows=P.rare?.per_type?.rows||[];if(!rows.length){host.innerHTML=emptyHTML('No rare populations for threshold sensitivity');return}const groups=Object.entries(sensitivityRules||{});host.innerHTML=`<div class="panel"><div class="panel-title"><div class="panel-title-main">Failure-threshold sensitivity lab<div class="panel-subtitle">Reclassify provisional archetypes live; canonical benchmark files remain unchanged</div></div><div class="panel-actions"><button class="btn ghost compact" id="resetFailureRules">Reset canonical thresholds</button><button class="btn ghost compact" id="failureSensitivityPng">Export PNG</button></div></div><div class="panel-body"><div class="explore-banner"><b>Exploratory view.</b> Slider changes affect only this browser view and are never written back to the canonical benchmark result.</div><div class="threshold-grid">${groups.map(([g,obj])=>`<div class="threshold-card"><h4>${esc(failureLabel(g==='batch_fragmentation'?'batch_driven_fragmentation':g))}</h4>${Object.entries(obj).map(([k,v])=>thresholdControl(g,k,v)).join('')}</div>`).join('')}</div><div class="grid-half" style="margin-top:12px"><div><div id="failureSensitivityPlot" class="plot smallplot"></div></div><div id="failureSensitivitySummary"></div></div></div></div>`;document.querySelectorAll('.rule-slider').forEach(el=>el.oninput=()=>{const g=el.dataset.group,k=el.dataset.key,v=k==='min_clusters'?Math.round(Number(el.value)):Number(el.value);sensitivityRules[g][k]=v;document.getElementById(`ruleval-${g}-${k}`).textContent=fmt(v);updateFailureSensitivity()});document.getElementById('resetFailureRules').onclick=()=>{sensitivityRules=cloneJSON(P.failure_rules||{});renderFailureSensitivity()};document.getElementById('failureSensitivityPng').onclick=()=>downloadPlot('failureSensitivityPlot','scrarebench_failure_threshold_sensitivity');updateFailureSensitivity()}
function updateFailureSensitivity(){const rows=P.rare?.per_type?.rows||[],counts={},changed=[];rows.forEach(row=>{const c=classifyWithRules(row,sensitivityRules),primary=c.primary;counts[primary]=(counts[primary]||0)+1;const canonical=primaryFailure(row);if(primary!==canonical)changed.push({cell_type:row.cell_type,canonical,exploratory:primary,matches:c.matches.join('; ')})});const order=['preserved','resolution_limited','batch_driven_fragmentation','lineage_leakage','lineage_assimilation','mixed_or_uncertain'];Plotly.react('failureSensitivityPlot',[{type:'bar',x:order.map(x=>counts[x]||0),y:order.map(failureLabel),orientation:'h'}],{margin:{l:190,r:20,t:20,b:40},xaxis:{title:'Rare populations'},paper_bgcolor:'white',plot_bgcolor:'white'},{responsive:true,displaylogo:false});const summary=document.getElementById('failureSensitivitySummary');if(summary)summary.innerHTML=`<div class="cards">${card('Changed classifications',changed.length,'relative to canonical thresholds')}${card('Preserved now',counts.preserved||0,`${rows.length} evaluated populations`)}</div>${changed.length?tableHTML({columns:['cell_type','canonical','exploratory','matches'],rows:changed},'failureChangedTable',{showSearch:false}):emptyHTML('No classifications changed','Current sliders reproduce the canonical result.')}`;if(changed.length)wireTable({columns:['cell_type','canonical','exploratory','matches'],rows:changed},'failureChangedTable')}
function renderResolutionSensitivity(){const host=document.getElementById('resolutionSensitivityHost');if(!host)return;const data=P.rare?.resolution_sensitivity||{columns:[],rows:[]},rows=data.rows||[];if(!rows.length){host.innerHTML=emptyHTML('No resolution sweep was stored','Add multiple values to EvaluationConfig.resolution_sweep to inspect cluster-dependent rare metrics across resolutions.');return}const types=[...new Set(rows.map(r=>String(r.cell_type)))].sort(),initial=rareState.focus&&types.includes(String(rareState.focus))?String(rareState.focus):types[0];host.innerHTML=`<div class="panel"><div class="panel-title"><div class="panel-title-main">Resolution sensitivity<div class="panel-subtitle">Majority-vote and cluster-recovery diagnostics across the stored Leiden sweep</div></div><div class="panel-actions"><button class="btn ghost compact" id="resolutionPng">Export PNG</button></div></div><div class="panel-body"><div class="row"><div style="min-width:260px"><label for="resolutionCellType">Rare population</label><select id="resolutionCellType">${types.map(x=>`<option ${x===initial?'selected':''}>${esc(x)}</option>`).join('')}</select></div></div><div class="explore-banner"><b>Interpretation:</b> majority-vote F1 is intentionally retained but is Leiden-resolution dependent. Best-cluster F1 avoids competition for majority ownership. The primary support-adjusted kNN local-recovery metric is computed from the canonical kNN graph and is independent of the Leiden resolution sweep (it still depends on the recorded kNN graph contract).</div><div id="resolutionSensitivityPlot" class="plot smallplot"></div></div></div>`;document.getElementById('resolutionCellType').onchange=updateResolutionSensitivity;document.getElementById('resolutionPng').onclick=()=>downloadPlot('resolutionSensitivityPlot','scrarebench_rare_resolution_sensitivity');updateResolutionSensitivity()}
function updateResolutionSensitivity(){const type=document.getElementById('resolutionCellType')?.value,rows=(P.rare?.resolution_sensitivity?.rows||[]).filter(r=>String(r.cell_type)===String(type)).sort((a,b)=>Number(a.resolution)-Number(b.resolution));if(!rows.length)return;const x=rows.map(r=>Number(r.resolution)),custom=rows.map(r=>[r.n_clusters]);const traces=[['f1','Majority-vote F1'],['best_cluster_f1','Best-cluster F1'],['inverse_purity','Dominant-cluster capture']].map(([k,label])=>({type:'scatter',mode:'lines+markers',name:label,x,y:rows.map(r=>r[k]),customdata:custom,hovertemplate:'Resolution %{x}<br>Score %{y:.3f}<br>Clusters %{customdata[0]}<extra>'+label+'</extra>'}));Plotly.react('resolutionSensitivityPlot',traces,{margin:{l:55,r:20,t:20,b:50},xaxis:{title:'Leiden resolution'},yaxis:{title:'Score',range:[0,1]},legend:{orientation:'h'},paper_bgcolor:'white',plot_bgcolor:'white'},{responsive:true,displaylogo:false})}
function sandboxRecompute(){const out=document.getElementById('sandboxOutput');if(!out||!P.points)return;const res=document.getElementById('sandboxResolution')?.value,enc=P.points.resolution_clusters?.[res];if(!enc){out.innerHTML=emptyHTML('No cluster assignment for this resolution');return}const excluded=new Set([...document.getElementById('sandboxBatches').selectedOptions].map(o=>o.value)),merge=new Set([...document.getElementById('sandboxMergeLabels').selectedOptions].map(o=>o.value)),mergedName=(document.getElementById('sandboxMergeName').value||'Merged label').trim(),n=P.points.x.length,active=[];for(let i=0;i<n;i++)if(!excluded.has(field('batch',i)))active.push(i);const labelAt=i=>merge.has(field('celltype',i))?mergedName:field('celltype',i),clusters={},labels=new Set();active.forEach(i=>{const c=encodedField(enc,i),l=labelAt(i);labels.add(l);if(!clusters[c])clusters[c]={};clusters[c][l]=(clusters[c][l]||0)+1});const mapping={};Object.entries(clusters).forEach(([c,obj])=>{mapping[c]=Object.entries(obj).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]))[0][0]});const stats={};labels.forEach(l=>stats[l]={tp:0,fp:0,fn:0,support:0});let correct=0;active.forEach(i=>{const t=labelAt(i),p=mapping[encodedField(enc,i)];stats[t].support++;if(t===p){correct++;stats[t].tp++}else{stats[t].fn++;if(!stats[p])stats[p]={tp:0,fp:0,fn:0,support:0};stats[p].fp++}});const rows=Object.entries(stats).filter(([,v])=>v.support>0).map(([cell_type,v])=>{const precision=v.tp/(v.tp+v.fp||1),recall=v.tp/(v.tp+v.fn||1),f1=(precision+recall)?2*precision*recall/(precision+recall):0,dominantCount=Math.max(0,...Object.values(clusters).map(obj=>Number(obj[cell_type]||0))),inverse_purity=v.support?dominantCount/v.support:0;return {cell_type,support:v.support,precision,recall,f1,inverse_purity}}).sort((a,b)=>a.cell_type.localeCompare(b.cell_type));const macro=rows.length?rows.reduce((a,r)=>a+r.f1,0)/rows.length:null,acc=active.length?correct/active.length:null;out.innerHTML=`<div class="cards">${card('Active cells',active.length)}${card('Cell types',rows.length)}${card('Clusters',Object.keys(clusters).length)}${card('Accuracy',acc)}${card('Macro F1',macro)}</div><div class="explore-banner"><b>Modified exploratory view.</b> Excluded batches, merged labels, and alternate resolution are recomputed only in this browser and never replace canonical benchmark scores. Precision, recall, F1, and dominant-cluster capture are recomputed from the modified contingency table. Integration is <b>not</b> re-run and clusters are <b>not</b> recomputed: excluding a batch filters cells out of the existing clustering, which is not the same as having integrated the data without that batch.</div>${tableHTML({columns:['cell_type','support','precision','recall','f1','inverse_purity'],rows},'sandboxTable')}`;wireTable({columns:['cell_type','support','precision','recall','f1','inverse_purity'],rows},'sandboxTable')}
function renderExplorationSandbox(){const host=document.getElementById('sandboxHost');if(!host||!P.points)return;const resolutions=Object.keys(P.points.resolution_clusters||{}).sort((a,b)=>Number(a)-Number(b)),batches=P.points.fields?.batch?.categories||[],labels=P.points.fields?.celltype?.categories||[];if(!resolutions.length){host.innerHTML=emptyHTML('No stored resolution assignments for sandbox recomputation');return}host.innerHTML=`<div class="panel"><div class="panel-title"><div class="panel-title-main">No-code what-if sandbox<div class="panel-subtitle">Recompute majority-vote metrics after changing resolution, excluding batches, or merging reference labels</div></div><div class="panel-actions"><button class="btn" id="runSandbox">Recompute exploratory view</button></div></div><div class="panel-body"><div class="explore-banner"><b>Not a canonical benchmark result.</b> This panel is for hypothesis checking and sensitivity analysis. It never changes the saved scRareBench scores. Resolution options come from the stored resolution sweep; batch exclusion and label merging reuse those stored cluster assignments rather than re-running integration or clustering.</div><div class="sandbox-grid"><div><label>Leiden resolution</label><select id="sandboxResolution">${resolutions.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div><label>Exclude batches</label><select id="sandboxBatches" multiple>${batches.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div><label>Merge reference labels</label><select id="sandboxMergeLabels" multiple>${labels.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div><label>Merged label name</label><input id="sandboxMergeName" type="text" value="Merged label"></div></div><div id="sandboxOutput" style="margin-top:12px"></div></div></div>`;document.getElementById('runSandbox').onclick=sandboxRecompute;sandboxRecompute()}
