// ---------- Multi-seed / multi-run report layer (schema 1.5+) ----------
function activeRun(){return REPORT.runs.find(r=>r.run_id===activeRunId)||REPORT.runs[0]||null}
function includedRuns(){return REPORT.runs.filter(r=>r.included!==false)}
function seedLabel(run){return run?.method_seed===null||run?.method_seed===undefined?'Seed not recorded':`Seed ${run.method_seed}`}
function finiteNumbers(values){return values.filter(v=>typeof v==='number'&&Number.isFinite(v))}
