    // UI aliases retained for concise client rendering.
    stored,included,includedSeeds,excludedSeeds,subset,perType,rareSummary,rareRows,scenarios,resolution,scibMetrics,scibAggregates,
    // Canonical schema-1.5 aggregate keys match the Python-generated container.
    n_stored:stored,n_included:included,included_run_ids:incRuns.map(r=>r.run_id),included_seeds:includedSeeds,excluded_seeds:excludedSeeds,
    metrics_subset:subset,metrics_per_type:perType,rare_summary:rareSummary,rare_per_type:rareRows,rare_scenarios:scenarios,
