function findRow(rows,key,value){return (rows||[]).find(r=>String(r?.[key])===String(value))}
function metricFromRun(run,kind,key,subset='overall'){
  if(kind==='scib')return findRow(rowsAt(run,['scib','aggregates']),'metric',key)?.value??null;
  if(kind==='rare')return findRow(rowsAt(run,['rare','summary']),'metric',key)?.mean??null;
  if(kind==='subset')return findRow(rowsAt(run,['metrics','subset']),'subset',subset)?.[key]??null;
  return null;
}
function compatibilityProblem(base,run){
  if(!base)return null;
  for(const [field,label] of [['method_name','method'],['dataset_fingerprint','dataset/cell universe'],['configuration_hash','seed-independent method configuration']]){
    const a=base[field],b=run[field];if(a!=null&&b!=null&&String(a)!==String(b))return `${label} does not match (${a} vs ${b}).`;
  }
  if(run.method_seed!=null&&REPORT.runs.some(r=>r.method_seed===run.method_seed))return `Seed ${run.method_seed} is already stored. Duplicate seeds are not allowed.`;
  if(run.run_id&&REPORT.runs.some(r=>r.run_id===run.run_id))return `Run ${run.run_id} is already stored.`;
  return null;
}
function extractLegacyPayload(text){
  const marker='const P=';const start=text.indexOf(marker);if(start<0)throw new Error('No scRareBench payload was found.');let i=start+marker.length;while(/\s/.test(text[i]))i++;if(text[i]!=='{')throw new Error('Malformed legacy payload.');const begin=i;let depth=0,inString=false,escaped=false;for(;i<text.length;i++){const ch=text[i];if(inString){if(escaped){escaped=false;continue}if(ch==='\\'){escaped=true;continue}if(ch==='"')inString=false;continue}if(ch==='"'){inString=true;continue}if(ch==='{')depth++;else if(ch==='}'&&--depth===0)return JSON.parse(text.slice(begin,i+1));}throw new Error('Legacy payload did not terminate.');
}
function extractReportFromHTML(text){const doc=new DOMParser().parseFromString(text,'text/html'),node=doc.getElementById('scrarebench-report-data');if(node)return JSON.parse(node.textContent||'{}');const P0=extractLegacyPayload(text),meta=P0.meta||{};return {report_type:'scrarebench_multi_run',schema_version:'legacy',expected_seeds:[],runs:[{run_id:meta.run_id||`legacy-${Date.now()}`,method_seed:meta.method_seed??null,included:true,method_name:meta.method_name||String(meta.representation_key||'unknown').replace(/^X_/,''),configuration_hash:meta.configuration_hash||null,dataset_fingerprint:meta.dataset_fingerprint||meta.cell_order_sha256||null,cell_order_sha256:meta.cell_order_sha256||null,latent_sha256:meta.latent_sha256||null,payload:P0}]}}
function activateMultiSeedTabsAfterImport(){
  if(!isMultiSeed())return;
  S.seed_stability=true;
  const runsBtn=document.getElementById('tabbtn-runs');if(runsBtn)runsBtn.textContent='Runs & Seeds';
  if(document.getElementById('tabbtn-seed_stability'))return;
  const bar=document.getElementById('tabs'),panelHost=document.getElementById('panels');if(!bar||!panelHost)return;
  const b=document.createElement('button');b.className='tab-btn';b.textContent='Seed Stability';b.dataset.tab='seed_stability';b.id='tabbtn-seed_stability';b.setAttribute('role','tab');b.setAttribute('aria-controls','tab-seed_stability');b.setAttribute('aria-selected','false');
  const runsAnchor=document.getElementById('tabbtn-runs');bar.insertBefore(b,runsAnchor||null);
  const p=document.createElement('section');p.id='tab-seed_stability';p.className='tab-panel';p.setAttribute('role','tabpanel');p.setAttribute('aria-labelledby',b.id);p.innerHTML='<div class="loading">Open this tab to render its contents.</div>';
  const runsPanel=document.getElementById('tab-runs');panelHost.insertBefore(p,runsPanel||null);
  b.addEventListener('click',()=>openTab('seed_stability'));rendered.delete('seed_stability');
}
async function importRunFiles(fileList){
  const files=[...fileList];if(!files.length)return;let added=0;
  for(const file of files){try{const text=await file.text(),data=extractReportFromHTML(text),incoming=data.report_type==='scrarebench_multi_run'?(data.runs||[]):[];if(!incoming.length)throw new Error('The selected report contains no runs.');for(const raw of incoming){const run=cloneJSON(raw);run.included=run.included!==false;_decodeRunPayload(run.payload);const problem=compatibilityProblem(REPORT.runs[0],run);if(problem){toast(`${file.name}: ${problem}`,'error');continue}REPORT.runs.push(run);if(Number.isInteger(run.method_seed)&&!REPORT.expected_seeds.includes(run.method_seed))REPORT.expected_seeds.push(run.method_seed);recordEdit('add_run',{run_id:run.run_id,method_seed:run.method_seed,source_file:file.name});added++}}catch(err){console.error(err);toast(`${file.name}: ${err.message||err}`,'error')}}
  REPORT.expected_seeds=[...new Set((REPORT.expected_seeds||[]).filter(Number.isInteger))].sort((a,b)=>a-b);updateStoredAggregate();activateMultiSeedTabsAfterImport();renderSeedManager();if(added){toast(`Added ${added} run${added===1?'':'s'}. Save Updated Report to persist the change.`);renderRunsTab();renderSeedStability();rerenderActiveTab()}
}
function savedReportFilename(){const r=REPORT.runs[0]||{},method=(r.method_name||'method').replace(/[^A-Za-z0-9._-]+/g,'_'),seedPart=REPORT.runs.map(x=>x.method_seed).filter(x=>x!=null).join('-')||'runs';return `scRareBench_${method}_multiseed_${seedPart}.html`}
