function switchRun(runId){const run=REPORT.runs.find(r=>r.run_id===runId);if(!run)return;activeRunId=run.run_id;P=run.payload||{};_decodeRunPayload(P);S=P.sections||{};S.seed_stability=isMultiSeed();S.runs=true;F=P.features||{};activeFlow=null;lassoSelection.clear();rareState.scenario='';rareState.outcome='';rareState.failure='';rareState.query='';rareState.focus=null;rendered.clear();document.querySelectorAll('.tab-panel').forEach(p=>p.innerHTML='<div class="loading">Open this tab to render its contents.</div>');renderSeedManager();const current=document.querySelector('.tab-btn.active')?.dataset.tab||'overview';if(S[current])openTab(current,{scroll:false});else openTab('overview',{scroll:false})}
