  const host=document.getElementById('seedManager');if(!host)return;const active=activeRun(),inc=includedRuns().length,stored=REPORT.runs.length,expected=(REPORT.expected_seeds||[]).length;
  if(!isMultiSeed()){host.innerHTML=`<div class="seed-manager-card"><div><div class="eyebrow">Single-run report</div><b>${esc(seedLabel(active))} · canonical benchmark result</b><div class="note">Seed aggregation is hidden because only one run is stored. Provenance and hashes remain available.</div></div><div class="seed-manager-actions"><button class="btn light" id="openRunsManager">Run & Provenance</button><button class="btn" id="saveUpdatedReport">Save Updated Report</button></div></div>`;document.getElementById('openRunsManager').onclick=()=>openTab('runs');document.getElementById('saveUpdatedReport').onclick=saveUpdatedReport;return}
  host.innerHTML=`<div class="seed-manager-card"><div><div class="eyebrow">Multi-seed workspace</div><b>${esc(stored)} stored runs · ${esc(inc)} included in aggregate${expected?` · ${esc(expected)} planned seeds`:''}</b><div class="note">Aggregate statistics use included runs only. Excluding a run never deletes its data.</div></div><div class="seed-manager-actions"><label>Detailed run <select id="globalRunSelect">${REPORT.runs.map(r=>`<option value="${esc(r.run_id)}" ${r.run_id===activeRunId?'selected':''}>${esc(seedLabel(r))}${r.included===false?' · excluded':''}</option>`).join('')}</select></label><button class="btn light" id="openRunsManager">Runs & Seeds</button><button class="btn" id="saveUpdatedReport">Save Updated Report</button></div></div>`;
  document.getElementById('globalRunSelect').onchange=e=>switchRun(e.target.value);document.getElementById('openRunsManager').onclick=()=>openTab('runs');document.getElementById('saveUpdatedReport').onclick=saveUpdatedReport;
