tabBar.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const buttons=[...tabBar.querySelectorAll('.tab-btn')],cur=buttons.indexOf(document.activeElement);if(cur<0)return;e.preventDefault();let next=cur;if(e.key==='ArrowRight')next=(cur+1)%buttons.length;if(e.key==='ArrowLeft')next=(cur-1+buttons.length)%buttons.length;if(e.key==='Home')next=0;if(e.key==='End')next=buttons.length-1;buttons[next].focus();openTab(buttons[next].dataset.tab,{scroll:false})});

function figureCards(group){const figs=(P.figures||[]).map((f,i)=>({...f,_i:i})).filter(f=>!group||f.group===group);if(!figs.length)return '';return `<div class="fig-grid">${figs.map(f=>`<div class="figure-box" data-figure-card="${f._i}" data-figure-group="${esc(f.group)}" data-figure-search="${esc(((f.title||'')+' '+(f.name||'')+' '+(f.group||'')).toLowerCase())}"><div class="figure-media"><img class="zoomable-figure" data-fig-index="${f._i}" src="${f.uri}" alt="${esc(f.title||f.name)}"><div class="fig-actions"><button class="icon-btn fig-open" data-fig-index="${f._i}" title="Enlarge figure" aria-label="Enlarge figure">⤢</button><button class="icon-btn fig-download" data-fig-index="${f._i}" title="Download original figure" aria-label="Download original figure">↓</button></div></div><div class="cap"><b>${esc(f.title||f.name)}</b><br>${esc(f.group)} · ${esc(f.name)}</div></div>`).join('')}</div>`}
function bindFigureActions(scope=document){scope.querySelectorAll('.zoomable-figure,.fig-open').forEach(el=>el.addEventListener('click',()=>{modalLastFocus=el;const galleryCard=el.closest('#figureGallery [data-figure-card]');modalNavIndices=galleryCard?[...document.querySelectorAll('#figureGallery [data-figure-card]')].filter(c=>c.style.display!=='none').map(c=>Number(c.dataset.figureCard)):(P.figures||[]).map((_,i)=>i);openFigure(Number(el.dataset.figIndex))}));scope.querySelectorAll('.fig-download').forEach(el=>el.addEventListener('click',e=>{e.stopPropagation();downloadFigure(Number(el.dataset.figIndex))}))}
function openFigure(i){const figs=P.figures||[],f=figs[i];if(!f)return;modalIndex=i;modalZoom=1;const img=document.getElementById('modalImg');img.alt=f.title||f.name;document.getElementById('modalTitle').textContent=f.title||f.name;document.getElementById('modalFoot').textContent=f.group+' · '+f.name;document.getElementById('figModal').classList.add('open');document.getElementById('figModal').setAttribute('aria-hidden','false');img.onload=()=>fitModalImage();img.src=f.uri;if(img.complete)requestAnimationFrame(fitModalImage);document.getElementById('modalClose').focus()}
function fitModalImage(){const img=document.getElementById('modalImg'),stage=document.getElementById('modalStage');if(!img.naturalWidth||!stage.clientWidth)return;const maxW=Math.max(100,stage.clientWidth-48),maxH=Math.max(100,stage.clientHeight-48);modalFitScale=Math.min(1,maxW/img.naturalWidth,maxH/img.naturalHeight);applyModalSize()}
function applyModalSize(){const img=document.getElementById('modalImg');if(!img.naturalWidth)return;const scale=modalFitScale*modalZoom;img.style.width=Math.max(1,Math.round(img.naturalWidth*scale))+'px';const readout=document.getElementById('zoomReadout');if(readout)readout.textContent=Math.abs(scale-1)<.015?'100%':Math.round(scale*100)+'%'}
function setModalZoom(z){modalZoom=Math.min(5,Math.max(.5,z));applyModalSize()}
function navigateFigure(step){const figs=P.figures||[],nav=(modalNavIndices||[]).filter(i=>figs[i]);if(!nav.length)return;let pos=nav.indexOf(modalIndex);if(pos<0)pos=0;openFigure(nav[(pos+step+nav.length)%nav.length])}
function closeFigure(){const modal=document.getElementById('figModal');modal.classList.remove('open');modal.setAttribute('aria-hidden','true');modalLastFocus?.focus?.()}
function downloadFigure(i){const f=(P.figures||[])[i];if(!f)return;try{const a=document.createElement('a');a.href=f.uri;a.download=f.name||'scrarebench_figure.png';document.body.appendChild(a);a.click();a.remove();toast(`Saved ${f.name||'figure'}`)}catch(err){console.error(err);toast('Figure download failed.','error')}}
document.getElementById('modalClose').onclick=closeFigure;document.getElementById('zoomIn').onclick=()=>setModalZoom(modalZoom+.25);document.getElementById('zoomOut').onclick=()=>setModalZoom(modalZoom-.25);document.getElementById('zoomFit').onclick=()=>setModalZoom(1);document.getElementById('zoomActual').onclick=()=>setModalZoom(modalFitScale>0?1/modalFitScale:1);document.getElementById('modalDownload').onclick=()=>downloadFigure(modalIndex);document.getElementById('modalPrev').onclick=()=>navigateFigure(-1);document.getElementById('modalNext').onclick=()=>navigateFigure(1);document.getElementById('figModal').addEventListener('click',e=>{if(e.target.id==='figModal')closeFigure()});document.addEventListener('keydown',e=>{if(!document.getElementById('figModal').classList.contains('open'))return;if(e.key==='Escape')closeFigure();if(e.key==='ArrowLeft')navigateFigure(-1);if(e.key==='ArrowRight')navigateFigure(1)});window.addEventListener('resize',()=>{if(document.getElementById('figModal').classList.contains('open'))fitModalImage()});

function renderOverview(){if(!S.overview)return;const m=P.meta,r=P.rare||{},sc=P.scib||{};let cards=card('Cells',m.n_cells)+card('Cell types',m.n_cell_types)+card('Reference clusters',m.n_reference_clusters,m.cluster_count_warning?'Fewer clusters than reference cell types — majority-vote metrics have a structural ceiling':'Cluster count does not trigger the ceiling warning')+card('Batches',m.n_batches)+card('Latent dimensions',m.n_dimensions)+card('Rare populations',m.n_rare_types)+card('Rare cells',m.n_rare_cells);if(sc.aggregates){['Bio conservation','Batch correction','Total'].forEach(x=>{const v=findMetric(sc.aggregates,x);if(v!==null)cards+=scoreCard('scIB '+x,v)});}if(r.summary){['knn_local_recovery_adjusted','best_cluster_f1','inverse_purity','knn_local_recovery','f1'].forEach(x=>{const v=findMetric(r.summary,x);if(v!==null)cards+=scoreCard('Mean rare '+colLabel(x),v,'Unweighted mean across curated rare populations')});const pf=findMetric(r.summary,'preserved_fraction');if(pf!==null)cards+=card('Legacy preserved-rule fraction',pct(pf),`${Math.round(pf*(m.n_rare_types||0))} of ${m.n_rare_types||0} populations · majority-vote dependent`);const rlf=findMetric(r.summary,'resolution_limited_fraction');if(rlf!==null)cards+=card('Resolution-limited fraction (v2)',pct(rlf),`${Math.round(rlf*(m.n_rare_types||0))} of ${m.n_rare_types||0} populations · diagnostic, not preserved`)}const rows=r.per_type?.rows||[],preserved=rows.filter(x=>rareOutcome(x)==='preserved').length,notPreserved=rows.length-preserved,failCounts={};rows.filter(x=>rareOutcome(x)==='not_preserved').forEach(x=>{const k=primaryFailure(x)||'mixed_or_uncertain';failCounts[k]=(failCounts[k]||0)+1});const failureHtml=Object.entries(failCounts).sort((a,b)=>b[1]-a[1]).map(([k,v])=>failurePill(k,v)).join('');document.getElementById('tab-overview').innerHTML=`<div class="cards">${cards}</div><div class="panel"><div class="panel-title"><div class="panel-title-main">Run identity<div class="panel-subtitle">Keys used for evaluation and visualization</div></div></div><div class="panel-body"><div class="rare-focus"><span class="pill">${esc(m.representation_key)}</span><span class="pill">${esc(m.cluster_key)}</span><span class="pill">${esc(m.scib_backend)} ${esc(m.scib_backend_version)}</span>${m.embedding_warning?`<div class="callout" style="border-color:#efb46b;background:#fff9ef;margin-bottom:10px"><b>Embedding warning:</b> ${esc(m.embedding_warning)}</div>`:''}${m.cluster_count_warning?`<div class="callout" style="border-color:#efb46b;background:#fff9ef;margin-bottom:10px"><b>Cluster-count warning:</b> ${esc(m.n_reference_clusters)} reference clusters for ${esc(m.n_cell_types)} cell types. Majority-vote precision/recall/F1 remain reported for continuity, but the primary local diagnostic is support-adjusted kNN recovery; interpret it with best-cluster F1, dominant-cluster capture, and resolution sensitivity.</div>`:''}${r.status?.annotation_drift_warning?`<div class="callout" style="border-color:#efb46b;background:#fff9ef;margin-bottom:10px"><b>Scenario annotation warning:</b> Exploratory mode dropped or could not evaluate curated scenario rows. Inspect Rare-cell status and reproducibility metadata before interpreting scenario aggregates.</div>`:''}<div class="callout note" style="margin-bottom:10px"><b>Preserved outcome is legacy/provisional.</b> The rule-based preserved fraction is retained for continuity and still uses majority-vote precision/recall. Do not use it as the primary rare-preservation endpoint; prefer support-adjusted kNN recovery, full-space ASW, best-cluster F1, and dominant-cluster capture.</div><p class="note">The standard scIB-compatible layer and the scRareBench rare-cell layer are intentionally reported separately rather than collapsed into one unvalidated composite score.</p>${rows.length?`<div class="outcome-summary"><b>Legacy rule outcomes:</b>${outcomePill('preserved',preserved)}${outcomePill('not_preserved',notPreserved)}</div>${failureHtml?`<div class="status-line" style="margin-top:7px"><b>Failure modes among legacy not-preserved populations:</b> ${failureHtml}</div>`:''}`:''}</div></div></div><div class="grid-half"><div class="panel"><div class="panel-title"><div class="panel-title-main">scIB aggregate scores<div class="panel-subtitle">Standard scIB-compatible layer</div></div><div class="panel-actions"><button class="btn ghost compact" id="overviewScibPng">Export PNG</button></div></div><div class="panel-body"><div id="overviewScibPlot" class="plot smallplot"></div></div></div><div class="panel"><div class="panel-title"><div class="panel-title-main">Rare-cell summary scores<div class="panel-subtitle">Primary/additive rare-population diagnostics; legacy rule outcome is not plotted as a performance score</div></div><div class="panel-actions"><button class="btn ghost compact" id="overviewRarePng">Export PNG</button></div></div><div class="panel-body"><div id="overviewRarePlot" class="plot smallplot"></div></div></div></div>`;const scRows=(sc.aggregates?.rows||[]).filter(x=>typeof x.value==='number'&&Number.isFinite(x.value));if(scRows.length)Plotly.newPlot('overviewScibPlot',[{type:'bar',x:scRows.map(x=>x.value),y:scRows.map(x=>x.metric),orientation:'h',marker:{color:'#4866d5'}}],{margin:{l:150,r:20,t:15,b:40},xaxis:{range:[0,1],title:'Score'},paper_bgcolor:'white',plot_bgcolor:'white'},{responsive:true,displaylogo:false});else document.getElementById('overviewScibPlot').innerHTML=emptyHTML('No scIB aggregate scores');const rareKeys=['knn_local_recovery_adjusted','best_cluster_f1','inverse_purity','knn_local_recovery','f1'],rareRows=(r.summary?.rows||[]).filter(x=>rareKeys.includes(x.metric)&&typeof x.mean==='number'&&Number.isFinite(x.mean));if(rareRows.length)Plotly.newPlot('overviewRarePlot',[{type:'bar',x:rareRows.map(x=>x.mean),y:rareRows.map(x=>colLabel(x.metric)),orientation:'h',marker:{color:rareRows.map(x=>x.metric==='knn_local_recovery_adjusted'?'#4b63d2':'#8c78d8')}}],{margin:{l:230,r:20,t:15,b:40},xaxis:{range:rareRows.some(x=>String(x.metric).includes('knn_local_recovery'))?[-1,1]:[0,1],title:'Score'},paper_bgcolor:'white',plot_bgcolor:'white'},{responsive:true,displaylogo:false});else document.getElementById('overviewRarePlot').innerHTML=emptyHTML('No rare summary scores');document.getElementById('overviewScibPng').onclick=()=>downloadPlot('overviewScibPlot','scrarebench_overview_scib_scores');document.getElementById('overviewRarePng').onclick=()=>downloadPlot('overviewRarePlot','scrarebench_overview_rare_scores')}
function renderMetrics(){if(!S.metrics)return;const M=P.metrics||{};document.getElementById('tab-metrics').innerHTML=`<div class="panel"><div class="panel-title"><div class="panel-title-main">Overall / rare / non-rare benchmark metrics<div class="panel-subtitle">Global comparison by evaluation subset</div></div></div><div class="panel-body">${tableHTML(M.subset,'subsetTable')}</div></div><div class="panel"><div class="panel-title"><div class="panel-title-main">All cell-type metrics<div class="panel-subtitle">Sort, filter, and export without leaving the report</div></div></div><div class="panel-body"><p class="note">Headers are human-readable; hover a header for metric details where available. Historical majority-vote metrics are retained for continuity. New full-space ASW, best-cluster recovery and kNN local-recovery diagnostics are additive. Dashboard filters do not change canonical scores.</p>${tableHTML(M.per_type,'perTypeTable')}</div></div><div class="panel"><div class="panel-title">Metric glossary</div><div class="panel-body"><div class="glossary">${Object.entries(COLUMN_HELP).map(([k,v])=>`<div class="gloss-item"><b>${esc(colLabel(k))}</b><p>${esc(v)}</p></div>`).join('')}</div></div></div>`;wireTable(M.subset,'subsetTable');wireTable(M.per_type,'perTypeTable')}

function renderScib(){if(!S.scib)return;const X=P.scib||{};const metrics=X.metrics||{columns:[],rows:[]},aggregates=X.aggregates||{rows:[]};document.getElementById('tab-scib').innerHTML=`<div class="callout note" style="margin-bottom:14px">The scIB-compatible section is reported independently from scRareBench rare-cell diagnostics. Metrics requiring gene-level corrected expression, curated trajectories, or other unavailable inputs are explicitly marked <b>not applicable</b> rather than silently omitted.</div><div class="cards">${(aggregates.rows||[]).map(r=>scoreCard(r.metric,r.value,r.metric_type||'Aggregate score')).join('')||card('scIB status','No aggregate scores')}</div><div class="grid-half"><div class="panel"><div class="panel-title"><div class="panel-title-main">Interactive scIB score profile<div class="panel-subtitle">Computed metrics plus reported aggregate scores</div></div><div class="panel-actions"><button class="btn ghost compact" id="scibPng">Export PNG</button></div></div><div class="panel-body"><div id="scibPlot" class="plot smallplot"></div></div></div><div class="panel"><div class="panel-title"><div class="panel-title-main">Backend / reference configuration<div class="panel-subtitle">Configuration used by the scIB-compatible layer</div></div><div class="panel-actions"><button class="btn ghost compact" id="scibConfigDownload">Export JSON</button></div></div><div class="panel-body"><div class="pre">${esc(JSON.stringify(X.reference_config||{},null,2))}</div></div></div></div><div class="panel"><div class="panel-title">All scIB-compatible metrics</div><div class="panel-body">${tableHTML(metrics,'scibMetrics')}</div></div><div class="panel"><div class="panel-title">Metric availability and applicability</div><div class="panel-body">${tableHTML(X.status,'scibStatus')}</div></div><div class="panel"><div class="panel-title">Raw benchmarker result table</div><div class="panel-body">${tableHTML(X.results_wide,'scibWide')}</div></div>${figureCards('scIB')?`<div class="panel"><div class="panel-title">Backend-produced scIB figures</div><div class="panel-body">${figureCards('scIB')}</div></div>`:''}`;wireTable(metrics,'scibMetrics');wireTable(X.status,'scibStatus');wireTable(X.results_wide,'scibWide');const rows=[...(metrics.rows||[]),...(aggregates.rows||[])].filter(r=>typeof r.value==='number'&&Number.isFinite(r.value));if(rows.length)Plotly.newPlot('scibPlot',[{type:'bar',x:rows.map(r=>r.value),y:rows.map(r=>r.metric),orientation:'h',marker:{color:rows.map(r=>((r.metric_type||'').toLowerCase().includes('batch')||String(r.metric||'').toLowerCase()==='batch correction')?'#0f9b75':'#4968d8')}}],{height:Math.max(390,rows.length*28),margin:{l:200,r:20,t:20,b:40},xaxis:{title:'Score'},paper_bgcolor:'white',plot_bgcolor:'white'},{responsive:true,displaylogo:false});else document.getElementById('scibPlot').innerHTML=emptyHTML('No numeric scIB scores','Check metric availability and applicability below.');document.getElementById('scibPng').onclick=()=>downloadPlot('scibPlot','scrarebench_scib_metrics');document.getElementById('scibConfigDownload').onclick=()=>downloadText('scib_reference_config.json',JSON.stringify(X.reference_config||{},null,2),'application/json');bindFigureActions(document.getElementById('tab-scib'))}

function scenarioGuide(){return `<div class="scenario-guide"><div class="guide-card"><h4>GR — Globally Rare</h4><p>Rare globally while represented across multiple batches in the benchmark taxonomy.</p></div><div class="guide-card"><h4>LE — Locally Enriched</h4><p>Concentrated in a limited subset of batches or conditions.</p></div><div class="guide-card"><h4>SR — Sporadic Rare</h4><p>Sparse and limited to a small subset of batches or conditions.</p></div><div class="guide-card"><h4>DL — Distinct lineage</h4><p>A biologically distinct rare lineage or population rather than a rare state nested near a related abundant population.</p></div><div class="guide-card"><h4>RM — Related manifold / state</h4><p>A rare state or subtype biologically related to a more abundant or neighboring population; parent-lineage metadata is shown when curated.</p></div><div class="guide-card"><h4>Six scenarios</h4><p>GR-DL, GR-RM, LE-DL, LE-RM, SR-DL, and SR-RM combine distribution and topology classes.</p></div></div>`}

function scenarioSummaryPivotData(data){
  const source=data?.rows||[],order=['GR-DL','GR-RM','LE-DL','LE-RM','SR-DL','SR-RM'],by=new Map(source.map(r=>[String(r.scenario),r])),cols=['Metric',...order];
  const metricRows=[
    ['Rare populations','n_cell_types','count'],
    ['Support-adjusted kNN recovery','knn_local_recovery_adjusted_mean','score'],
    ['Best-cluster F1','best_cluster_f1_mean','score'],
    ['Dominant-cluster capture','inverse_purity_mean','score'],
    ['Raw kNN recovery','knn_local_recovery_mean','score'],
    ['Within-type batch NMI','within_type_batch_nmi_mean','score'],
    ['Legacy majority-vote F1','f1_mean','score'],
  ];
  const coreRows=metricRows.map(([label,key,type])=>{const row={Metric:label};order.forEach(sc=>{const v=by.get(sc)?.[key];row[sc]=type==='count'?fmtCount(Number(v)):fmtScore(Number(v))});return row});
  const archetypes=[['Preserved','preserved'],['Resolution limited','resolution_limited'],['Batch-driven fragmentation','batch_driven_fragmentation'],['Lineage leakage','lineage_leakage'],['Lineage assimilation','lineage_assimilation'],['Mixed / uncertain','mixed_or_uncertain']];
  const failureRows=archetypes.map(([label,key])=>{const row={Metric:label};order.forEach(sc=>{const r=by.get(sc)||{},count=Number(r[`v2_${key}_count`]),frac=Number(r[`v2_${key}_fraction`]);row[sc]=Number.isFinite(count)?`${fmtCount(count)}${Number.isFinite(frac)?` (${pct(frac)})`:''}`:'—'});return row});
  return {core:{columns:cols,rows:coreRows},failure:{columns:cols,rows:failureRows}};
}
function scenarioSummaryPivot(data){
  const pivot=scenarioSummaryPivotData(data);
  return `<div class="scenario-pivot-stack"><div><h4>Core recovery metrics</h4>${tableHTML(pivot.core,'rareScenarioCorePivot',{showSearch:false})}</div><div><h4>Resolution-aware failure profile</h4>${tableHTML(pivot.failure,'rareScenarioFailurePivot',{showSearch:false})}</div><div class="note">The readable pivot above keeps the six canonical scenarios as columns. The complete 62-column source table remains available through <b>Export full raw scenario CSV</b>.</div><button class="btn ghost compact" id="rareScenarioRawExport">Export full raw scenario CSV</button></div>`;
}

function scenarioCard(c){const metrics=[['Adjusted local',c.knn_local_recovery_adjusted_mean],['Best F1',c.best_cluster_f1_mean],['Capture',c.inverse_purity_mean],['Raw local',c.knn_local_recovery_mean],['Legacy F1',c.f1_mean]].filter(([,v])=>v!==null&&v!==undefined&&Number.isFinite(Number(v))),failures=(c.failures||[]).map(f=>failurePill(f.failure_archetype,f.count)).join(''),cells=(c.rows||[]).map(r=>`<div class="cell-mini" role="button" tabindex="0" data-cell="${esc(r.cell_type)}"><span class="ct" title="${esc(r.cell_type)}">${esc(r.cell_type)}</span><span class="score">Adjusted local ${esc(fmtScore(r.knn_local_recovery_adjusted))} · ${esc(failureLabel(primaryFailure(r)))}</span></div>`).join(''),empty=c.is_empty?'<span class="note">No registered rare populations in this dataset.</span>':'';return `<div class="scenario-card ${selectedScenario===c.scenario?'active':''}" role="button" tabindex="0" data-scenario-card="${esc(c.scenario)}"><div class="row" style="justify-content:space-between"><h4>${esc(c.scenario)}</h4><span class="status">${esc(c.n_cell_types)} types</span></div><div class="scenario-meta">${esc(fmtCount(c.total_cells))} cells · Legacy preserved-rule ${esc(pct(c.preserved_fraction))}</div><div class="mini-metrics">${metrics.map(([k,v])=>`<div class="mini-metric"><b>${esc(fmtScore(v))}</b><span>${esc(k)}</span></div>`).join('')}</div><div class="failure-list">${c.is_empty?empty:(failures||'<span class="note">No failure labels</span>')}</div><div class="cell-mini-list">${cells}</div></div>`}

function renderScenarioSelector(){const box=document.getElementById('scenarioSelector');if(!box)return;const cats=P.rare.category_breakdown||[];box.innerHTML=cats.map(c=>`<button class="scenario-chip ${selectedScenario===c.scenario?'active':''}" data-scenario-select="${esc(c.scenario)}">${esc(c.scenario)}</button>`).join('');box.querySelectorAll('[data-scenario-select]').forEach(b=>b.onclick=()=>{selectedScenario=b.dataset.scenarioSelect;renderScenarioBreakdown();renderScenarioSelector();renderScenarioDetail()})}

function renderScenarioBreakdown(){const box=document.getElementById('scenarioBreakdown');if(!box)return;const cats=P.rare.category_breakdown||[];if(!cats.length){box.innerHTML=emptyHTML('No scenario-level breakdown','Scenario analysis was disabled or no curated scenario metadata was available.');return}box.innerHTML=`<div class="scenario-grid">${cats.map(scenarioCard).join('')}</div>`;box.querySelectorAll('[data-scenario-card]').forEach(el=>{const act=e=>{if(e.target.closest('[data-cell]'))return;selectedScenario=el.dataset.scenarioCard;renderScenarioBreakdown();renderScenarioSelector();renderScenarioDetail()};el.addEventListener('click',act);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();act(e)}})});box.querySelectorAll('[data-cell]').forEach(el=>{const act=e=>{e.stopPropagation();const row=P.rare.per_type.rows.find(r=>String(r.cell_type)===el.dataset.cell);if(row)selectRare(row,true)};el.addEventListener('click',act);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();act(e)}})})}
